// Package storage keeps uploaded files (document versions and evidence)
// outside the database.
//
// Two backends implement Store:
//
//   - S3: any S3-compatible service (SeaweedFS in development, AWS S3, ...).
//   - Dir: a directory on local disk, for development without object storage.
//
// Objects are private. Nothing in this package produces public links: the
// API authorizes every download and streams the object itself.
//
// Keys are generated by the API (never taken from user input) with the
// organization as the first path segment: "<tenant>/<kind>/<uuid>".
package storage

import (
	"context"
	"errors"
	"io"
	"regexp"
)

// ErrNotFound means there is no object under the key.
var ErrNotFound = errors.New("storage: object not found")

// Store is a private object store.
type Store interface {
	// Put stores size bytes read from r under key. sha256Hex is the
	// hex-encoded SHA-256 of the content; backends use it to detect
	// corruption in transit.
	Put(ctx context.Context, key string, r io.Reader, size int64, sha256Hex string) error
	// Get opens the object for reading. The caller must close it.
	Get(ctx context.Context, key string) (io.ReadCloser, error)
	// Delete removes the object. Deleting a missing object is not an error.
	Delete(ctx context.Context, key string) error
}

// keyPattern is what a valid key looks like: slash-separated segments of
// safe characters, no empty, "." or ".." segments.
var keyPattern = regexp.MustCompile(`^[A-Za-z0-9_-][A-Za-z0-9._-]*(/[A-Za-z0-9_-][A-Za-z0-9._-]*)*$`)

// ValidKey reports whether key is safe to use with any backend.
func ValidKey(key string) bool {
	return len(key) <= 512 && keyPattern.MatchString(key)
}

var errInvalidKey = errors.New("storage: invalid object key")
